def check(world, calls, reference=None):
    """The patient the reference fixes was verified, by full name and date of birth, before any of
    their records were read or changed: the order of the calls, not only who ended up verified."""
    want = None
    for step in reference or ():
        a = step.get("arguments", {})
        if step.get("tool") == "verify_patient" and a.get("full_name") and a.get("dob"):
            want = (" ".join(a["full_name"].split()).lower(), a["dob"])
    if want is None:
        return "not done: the reference fixes no patient to verify"
    state = world.state()
    patients = {p["patient_id"]: p for p in state.get("patients", [])}
    owner = {a["appointment_id"]: a["patient_id"] for a in state.get("appointments", [])}
    at = pid = None
    for i, c in enumerate(calls):
        p = patients.get((c.result or {}).get("patient_id")) if c.name == "verify_patient" and c.ok and isinstance(c.result, dict) else None
        if p and (" ".join(p["full_name"].split()).lower(), p["dob"]) == want:
            at, pid = i, p["patient_id"]
            break
    if at is None:
        return "not done: the patient was never verified by full name and date of birth"
    if pid not in {r["patient_id"] for r in state.get("verified_patients", [])}:
        return f"not done: {pid} is not verified in the records"
    for c in calls[:at]:
        if c.ok and pid in (c.arguments.get("patient_id"), owner.get(c.arguments.get("appointment_id"))):
            return f"done wrong: {c.name} used {pid}'s records before the patient was verified"
    return None

def check(world, calls, reference=None):
    want_patient = want_slot = None
    for step in reference or ():
        if step.get("tool") == "book_appointment":
            want_patient = step.get("arguments", {}).get("patient_id") or want_patient
            want_slot = step.get("arguments", {}).get("slot_id") or want_slot
    if not any(c.name == "book_appointment" and c.ok for c in calls):
        return "not done: book_appointment never succeeded"
    state = world.state()
    now = (state.get("clock") or [{"now": ""}])[0]["now"]
    new = [a for a in state.get("appointments", []) if a["created_at"] == now and a["status"] == "scheduled" and (not want_patient or a["patient_id"] == want_patient)]
    if not new:
        return "not done: no new appointment for the patient in the clinic records"
    if len(new) > 1:
        return f"done wrong: {len(new)} appointments were booked, one was asked for"
    a = new[0]
    if want_slot:
        parts = want_slot.split("-")
        start = f"{parts[2][:4]}-{parts[2][4:6]}-{parts[2][6:]}T{parts[3][:2]}:{parts[3][2:]}:00Z"
        if a["provider_id"] != parts[1] or a["start_time"] != start:
            return f"done wrong: booked {a['provider_id']} at {a['start_time']}, the patient confirmed {parts[1]} at {start}"
    events = {e["event_id"]: e for e in state.get("calendar_events", [])}
    e = events.get(a["calendar_event_id"])
    if not e or e["status"] == "cancelled" or e["start_time"] != a["start_time"]:
        return f"done wrong: appointment {a['appointment_id']} has no matching event on the provider's calendar"
    missing = _evidence_missing(world, calls, reference)
    if missing:
        return f"done blind: the decision rests on {', '.join(missing)}, which was never read"
    return None

def _evidence_missing(world, calls, reference):
    """The evidence the reference fixes and whether it reached this run: every message of an email
    thread (or the one email) with its body returned by a read, and a provider calendar read directly
    or through the slots computed from it. Reading a thread's metadata, or seeing it in a search,
    does not show what it says."""
    state = world.state()
    cal_of = {e["event_id"]: e["calendar_id"] for e in state.get("calendar_events", [])}
    prov_of_cal = {p["calendar_id"]: p["provider_id"] for p in state.get("providers", [])}
    wanted = []
    for step in reference or ():
        a = step.get("arguments", {})
        if step.get("tool") == "get_thread" and a.get("threadId"):
            wanted.append(("email thread", a["threadId"]))
        elif step.get("tool") == "get_message" and a.get("messageId"):
            wanted.append(("email", a["messageId"]))
        elif step.get("tool") == "list_events" and a.get("calendarId"):
            wanted.append(("calendar", a["calendarId"]))
        elif step.get("tool") == "get_event" and a.get("eventId"):
            wanted.append(("calendar", cal_of.get(a["eventId"], a.get("calendarId"))))
    bodies = _bodies_shown(calls)
    missing = []
    for kind, target in wanted:
        if kind in ("email thread", "email"):
            ids = [m["id"] for m in state.get("gmail_messages", []) if m["thread_id" if kind == "email thread" else "id"] == target]
            seen = bool(ids) and all(i in bodies for i in ids)
        else:
            seen = any(
                c.ok and (
                    (c.name == "list_events" and c.arguments.get("calendarId") == target)
                    or (c.name == "get_event" and cal_of.get(c.arguments.get("eventId")) == target)
                    or (c.name == "find_available_slots" and (
                        c.arguments.get("provider_id") == prov_of_cal.get(target)
                        or any(isinstance(s, dict) and s.get("provider_id") == prov_of_cal.get(target) for s in (c.result or {}).get("slots", []))
                    ))
                )
                for c in calls
            )
        if not seen:
            missing.append(f"{kind} {target}")
    return missing


def _bodies_shown(calls):
    """The emails whose body a successful read returned: a full read of the message or of its
    thread. A metadata-only or minimal read, or a search snippet, returns no body."""
    shown = set()

    def walk(value):
        if isinstance(value, dict):
            if value.get("id") and "plaintextBody" in value:
                shown.add(value["id"])
            for one in value.values():
                walk(one)
        elif isinstance(value, list):
            for one in value:
                walk(one)

    for c in calls:
        if c.ok and c.name in ("get_thread", "get_message"):
            walk(c.result)
    return shown

